  "inlineSchema": "// ---------------------------------------------------------------------------\n// NOVA — Phase 1 data model\n//\n// Design notes\n// ------------\n// * Everything user-owned carries a `userId` and cascades on user deletion.\n//   Every query in the app filters by `userId`; the indexes below are built\n//   around that access pattern.\n// * `Task` already carries nullable foreign keys for the Phase 2+ domain\n//   objects (project, goal, habit, meeting, event, milestone). They are plain\n//   nullable columns today so that adding the owning tables later is an\n//   additive migration (add table + add FK constraint) rather than a rewrite\n//   of the task table and every query that touches it.\n// * XP is an append-only ledger (`XpTransaction`). `UserStats.totalXp` is a\n//   cached rollup of that ledger and is only ever mutated inside the same\n//   database transaction that writes the ledger row.\n// ---------------------------------------------------------------------------\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ---------------------------------------------------------------------------\n// Enums\n// ---------------------------------------------------------------------------\n\nenum Priority {\n  LOW\n  MEDIUM\n  HIGH\n  URGENT\n}\n\n/// Where an XP ledger entry came from. Phase 2+ will add STREAK_BONUS,\n/// HABIT_COMPLETION, GOAL_MILESTONE, FOCUS_SESSION, ACHIEVEMENT.\nenum XpSource {\n  TASK_COMPLETION\n  ADJUSTMENT\n}\n\n/// AWARD adds XP, REVERSAL takes it back when the underlying event is undone.\n/// Storing both as ledger rows keeps the running total auditable instead of\n/// destructively editing history.\nenum XpEntryKind {\n  AWARD\n  REVERSAL\n}\n\n// ---------------------------------------------------------------------------\n// Identity\n// ---------------------------------------------------------------------------\n\nmodel User {\n  id           String @id @default(cuid())\n  email        String @unique\n  /// scrypt hash, formatted as `scrypt$N$r$p$salt$derivedKey`.\n  passwordHash String\n  name         String\n\n  /// IANA timezone (e.g. \"Europe/Berlin\"). All \"today\"/streak logic resolves\n  /// the calendar day through this, never through the server's clock.\n  timezone String @default(\"UTC\")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  sessions       Session[]\n  tasks          Task[]\n  categories     Category[]\n  xpTransactions XpTransaction[]\n  stats          UserStats?\n\n  @@index([email])\n}\n\n/// Opaque server-side sessions. Phase 2 can add an `Account` table keyed by\n/// (provider, providerAccountId) for OAuth without touching this model: the\n/// session is already decoupled from the credential that created it.\nmodel Session {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  /// SHA-256 of the cookie token. The raw token is never persisted, so a\n  /// database leak does not hand over live sessions.\n  tokenHash  String   @unique\n  expiresAt  DateTime\n  createdAt  DateTime @default(now())\n  lastUsedAt DateTime @default(now())\n\n  @@index([userId])\n  @@index([expiresAt])\n}\n\n// ---------------------------------------------------------------------------\n// Task domain\n// ---------------------------------------------------------------------------\n\nmodel Category {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  name  String\n  /// Design-token name (see src/config/categories.ts). Storing a token rather\n  /// than a hex value keeps categories theme-aware.\n  color String  @default(\"slate\")\n  icon  String?\n\n  isArchived Boolean @default(false)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  tasks Task[]\n\n  @@unique([userId, name])\n  @@index([userId, isArchived])\n}\n\nmodel Task {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  title       String\n  description String?\n  completed   Boolean  @default(false)\n  priority    Priority @default(MEDIUM)\n\n  categoryId String?\n  category   Category? @relation(fields: [categoryId], references: [id], onDelete: SetNull)\n\n  /// Calendar date in the user's timezone, stored as a DATE so it never shifts\n  /// when the server and the user disagree about the current offset.\n  dueDate DateTime? @db.Date\n  /// Wall-clock \"HH:mm\" in the user's timezone. Kept separate from dueDate so\n  /// an all-day task and a timed task are distinguishable.\n  dueTime String?\n\n  estimatedMinutes Int?\n\n  /// Authoritative XP for this task. Written by the server from the priority\n  /// default (or an explicit, validated user override) — never trusted from\n  /// the client at completion time.\n  xpReward Int @default(20)\n\n  /// Number of times this task has transitioned false -> true. Used as the\n  /// ledger cycle key so re-completing a reopened task cannot double-award.\n  completionCount Int @default(0)\n\n  // -- Phase 2+ forward references -----------------------------------------\n  // Nullable, unconstrained today. Adding the owning table later is a purely\n  // additive migration; no column on this table has to change.\n  projectId   String?\n  goalId      String?\n  habitId     String?\n  meetingId   String?\n  eventId     String?\n  milestoneId String?\n\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n  completedAt DateTime?\n\n  xpTransactions XpTransaction[]\n\n  @@index([userId])\n  @@index([completed])\n  @@index([dueDate])\n  @@index([userId, completed])\n  @@index([userId, dueDate])\n  // Serves the dashboard's \"open tasks, soonest first\" query in one scan.\n  @@index([userId, completed, dueDate])\n  @@index([userId, categoryId])\n  @@index([userId, completedAt])\n  @@index([projectId])\n  @@index([goalId])\n  @@index([habitId])\n}\n\n// ---------------------------------------------------------------------------\n// Progression\n// ---------------------------------------------------------------------------\n\n/// Append-only XP ledger. Never updated or deleted in normal operation.\nmodel XpTransaction {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  /// Signed: positive for AWARD, negative for REVERSAL. Summing the column\n  /// for a user always reproduces UserStats.totalXp.\n  amount Int\n  source XpSource    @default(TASK_COMPLETION)\n  kind   XpEntryKind @default(AWARD)\n\n  taskId String?\n  task   Task?   @relation(fields: [taskId], references: [id], onDelete: Cascade)\n\n  /// Which completion cycle of the task this entry belongs to. Together with\n  /// the unique constraint below this makes double-awarding impossible at the\n  /// database level, not just in application code.\n  cycle Int @default(0)\n\n  description String?\n  createdAt   DateTime @default(now())\n\n  @@unique([taskId, kind, cycle])\n  @@index([userId, createdAt])\n  @@index([userId, source])\n  @@index([taskId])\n}\n\n/// Cached aggregates. Always written inside the same transaction as the event\n/// that changes them, so they cannot drift from the ledger.\nmodel UserStats {\n  id     String @id @default(cuid())\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  totalXp Int @default(0)\n  level   Int @default(1)\n\n  currentStreak     Int     @default(0)\n  longestStreak     Int     @default(0)\n  /// \"YYYY-MM-DD\" as it read on the user's own calendar. Deliberately a string\n  /// rather than a timestamp: a local calendar day is not a point in time, and\n  /// storing it as one is what makes streaks break across timezones.\n  lastCompletedDate String?\n\n  tasksCompleted Int @default(0)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n",
